UPDATE `user` u INNER JOIN `student` s ON u.user_id = s.user_id
u.avatar = #{avatar}, u.nickname = #{nickname}, u.real_name = #{realName}, u.phone = #{phone}, u.email = #{email}, u.gender = #{gender},
WHERE s.student_id = #{studentId}

UPDATE `student`
major = #{major}, grade = #{grade}, job_status = #{jobStatus}, bio = #{bio}, job_direction = #{jobDirection}, intent_city = #{intentCity}, expected_salary = #{expectedSalary},
WHERE student_id = #{studentId}
